package com.chessedu.platform.classes.dto;

import com.chessedu.platform.classes.model.ClassSessionStatus;

import java.time.Instant;
import java.util.UUID;

/**
 * Outbound shape for a single scheduled meeting. {@code patternId} is
 * non-null only for sessions generated by a pattern — ad-hoc sessions
 * come back with {@code patternId = null}.
 */
public record ClassSessionView(
        UUID id,
        UUID classId,
        UUID patternId,
        Instant startsAt,
        Instant endsAt,
        ClassSessionStatus status,
        String notes
) {}
